-- ============================================================================
-- C02 · Plan contable — 2b · LA RESERVA DEL BOE de «qué se apunta aquí».
-- GENERADA por scripts/conta/plan.mjs: no se edita a mano.
--
-- Respuesta 4 del C02: toda cuenta de apunte sin texto propio ni heredado
-- enseña la primera frase de la DEFINICIÓN de la quinta parte del BOE, la del
-- código más cercano hacia arriba que la tenga, con «(PGC)» al final. Aquí
-- solo se guarda la de cada código que el BOE define; la herencia se resuelve
-- al enseñar. plain_name no se toca: cuando llegue el texto de hostelería, lo
-- sustituye sin migración.
--
-- pymes: 450 de 779 códigos con definición propia.
-- general: 492 de 907 códigos con definición propia.
--
-- SOLO AÑADE una columna a pgc_account (nueva en la 0100) y la rellena.
-- ============================================================================

alter table public.pgc_account add column if not exists boe_definition text;
comment on column public.pgc_account.boe_definition is 'Primera frase de la definición de este código en la quinta parte del plan (BOE), literal. Reserva de «qué se apunta aquí» cuando no hay plain_name propio ni heredado; se enseña con «(PGC)». La herencia se resuelve al enseñar.';

update public.pgc_account p set boe_definition = d.boe_definition
  from (values
  ('pymes', '100', '2008-01-01'::date, 'Capital escriturado en las sociedades que revistan forma mercantil, salvo cuando atendiendo a las características económicas de la emisión deba contabilizarse como pasivo financiero.'),
  ('pymes', '101', '2008-01-01'::date, 'Capital de las entidades sin forma mercantil.'),
  ('pymes', '102', '2008-01-01'::date, 'Corresponde a las empresas individuales.'),
  ('pymes', '103', '2008-01-01'::date, 'Capital social escriturado pendiente de desembolso no exigido a los socios o accionistas, excepto los desembolsos no exigidos correspondientes a los instrumentos financieros cuya calificación contable sea la de pasivo financiero.'),
  ('pymes', '104', '2008-01-01'::date, 'Capital social escriturado pendiente de desembolso que corresponde a aportaciones no dinerarias, excepto las aportaciones pendientes que correspondan a instrumentos financieros cuya calificación contable sea la de pasivo financiero.'),
  ('pymes', '108', '2008-01-01'::date, 'Acciones o participaciones propias adquiridas por la empresa (sección cuarta del capítulo IV del Texto Refundido de la Ley de Sociedades Anónimas y de la Ley de Sociedades de Responsabilidad Limitada).'),
  ('pymes', '109', '2008-01-01'::date, 'Acciones o participaciones propias adquiridas por la empresa en ejecución de un acuerdo de reducción de capital adoptado por la Junta General (artículo 170 del Texto Refundido de la Ley de Sociedades Anónimas y artículo 40 de la Ley de Sociedades de Responsabilidad Limitada).'),
  ('pymes', '110', '2008-01-01'::date, 'Aportación realizada por los accionistas o socios en el caso de emisión y colocación de acciones o participaciones a un precio superior a su valor nominal.'),
  ('pymes', '112', '2008-01-01'::date, 'Esta cuenta registrará la reserva establecida por el artículo 214 del Texto Refundido de la Ley de Sociedades Anónimas.'),
  ('pymes', '113', '2008-01-01'::date, 'Son las constituidas libremente por la empresa.'),
  ('pymes', '114', '2008-01-01'::date, 'Las establecidas por cualquier disposición legal con carácter obligatorio, distintas de las incluidas en otras cuentas de este subgrupo.'),
  ('pymes', '1140', '2008-01-01'::date, 'Las constituidas obligatoriamente en caso de adquisición de acciones o participaciones de la sociedad dominante y en tanto éstas no sean enajenadas (artículo 79.3 delTexto Refundido de la Ley de Sociedades Anónimas y artículo 40.bis de la Ley de Sociedades de Responsabilidad Limitada).'),
  ('pymes', '1141', '2008-01-01'::date, 'Son las establecidas en los estatutos de la sociedad.'),
  ('pymes', '1142', '2008-01-01'::date, 'Nominal de las acciones o participaciones de la propia empresa adquiridas por ésta y amortizadas con cargo a beneficios o a reservas disponibles.También se incluirá el nominal de las acciones o participaciones de la propia empresa amortizadas, si han sido adquiridas por ésta a título gratuito.'),
  ('pymes', '1144', '2008-01-01'::date, 'Reservas que deban ser constituidas en caso de aceptación de acciones propias en garantía (artículo. 80.1 del Texto Refundido de la Ley de Sociedades Anónimas).'),
  ('pymes', '118', '2008-01-01'::date, 'Elementos patrimoniales entregados por los socios o propietarios de la empresa cuando actúen como tales, en virtud de operaciones no descritas en otras cuentas.'),
  ('pymes', '119', '2008-01-01'::date, 'Diferencias originadas como consecuencia de la conversión a euros de la cifra de capital de acuerdo con el contenido de la Ley 46/1998, de 17 de diciembre, sobre Introducción del Euro.'),
  ('pymes', '120', '2008-01-01'::date, 'Beneficios no repartidos ni aplicados específicamente a ninguna otra cuenta, tras la aprobación de las cuentas anuales y de la distribución de resultados.'),
  ('pymes', '121', '2008-01-01'::date, 'Resultados negativos de ejercicios anteriores.'),
  ('pymes', '129', '2008-01-01'::date, 'Resultado, positivo o negativo, del último ejercicio cerrado, pendiente de aplicación.'),
  ('pymes', '13', '2008-01-01'::date, 'Subvenciones donaciones y legados, no reintegrables, otorgados por terceros distintos a los socios o propietarios, recibidos por la empresa y contabilizados directamente en el patrimonio neto, hasta que de conformidad con lo previsto en las normas de registro y valoración, se produzca su transferencia o imputación a la cuenta de pérdidas y ganancias.'),
  ('pymes', '130', '2008-01-01'::date, 'Las concedidas por las Administraciones Públicas, tanto nacionales como internacionales, para el establecimiento o estructura fija de la empresa (activos no corrientes) cuando no sean reintegrables, de acuerdo con los criterios establecidos en las normas de registro y valoración.'),
  ('pymes', '131', '2008-01-01'::date, 'Las donaciones y legados concedidos por empresas o particulares, para el establecimiento o estructura fija de la empresa (activos no corrientes) cuando no sean reintegrables, de acuerdo con los criterios establecidos en las normas de registro y valoración.'),
  ('pymes', '132', '2008-01-01'::date, 'Las subvenciones, donaciones y legados concedidos que no figuran en las cuentas anteriores, cuando no sean reintegrables, y se encuentren pendientes de imputar al resultado de acuerdo con los criterios establecidos en las normas de registro y valoración.'),
  ('pymes', '137', '2008-01-01'::date, 'Ventajas fiscales materializadas en diferencias permanentes y deducciones y bonificaciones que, por tener una naturaleza económica asimilable a las subvenciones, son objeto de imputación a la cuenta de pérdidas y ganancias en varios ejercicios.'),
  ('pymes', '14', '2008-01-01'::date, 'Obligaciones expresas o tácitas a largo plazo, claramente especificadas en cuanto a su naturaleza, pero que, en la fecha de cierre del ejercicio, son indeterminadas en cuanto a su importe exacto o a la fecha en que se producirán.'),
  ('pymes', '141', '2008-01-01'::date, 'Importe estimado de deudas tributarias cuyo pago está indeterminado en cuanto a su importe exacto o a la fecha en que se producirá, dependiendo del cumplimiento o no de determinadas condiciones.'),
  ('pymes', '142', '2008-01-01'::date, 'Pasivos no financieros surgidos por obligaciones de cuantía indeterminada no incluidas en ninguna de las restantes cuentas de este subgrupo; entre otras, las procedentes de litigios en curso, indemnizaciones u obligaciones derivados de avales y otras garantías similares a cargo de la empresa.'),
  ('pymes', '143', '2008-01-01'::date, 'Importe estimado de los costes de desmantelamiento o retiro del inmovilizado, así como la rehabilitación del lugar sobre el que se asienta.'),
  ('pymes', '145', '2008-01-01'::date, 'Obligaciones legales, contractuales o implícitas de la empresa o compromisos adquiridos por la misma, de cuantía indeterminada, para prevenir o reparar daños sobre el medio ambiente, salvo las que tengan su origen en el desmantelamiento, retiro o rehabilitación del inmovilizado, que se contabilizarán según lo establecido en la cuenta 143.'),
  ('pymes', '15', '2008-01-01'::date, 'Acciones u otras participaciones en el capital de la empresa que, atendiendo a las características económicas de la emisión, deban considerarse como pasivo financiero.'),
  ('pymes', '150', '2008-01-01'::date, 'Capital social escriturado y, en su caso, prima de emisión o asunción en las sociedades que revistan forma mercantil que, atendiendo a las características de la emisión, deba contabilizarse como pasivo financiero.'),
  ('pymes', '153', '2008-01-01'::date, 'Capital social escriturado no exigido correspondiente a los instrumentos financieros cuya calificación contable sea la de pasivo financiero.'),
  ('pymes', '154', '2008-01-01'::date, 'Capital social escriturado pendiente de desembolso por aportaciones no dinerarias, correspondiente a los instrumentos financieros cuya calificación contable sea la de pasivo financiero.'),
  ('pymes', '160', '2008-01-01'::date, 'Las contraídas con entidades de crédito vinculadas por préstamos recibidos y otros débitos, con vencimiento superior a un año.'),
